/// <reference types="expo/types" />

// `expo-env.d.ts` (which references expo/types) is generated by `expo start` and git-ignored,
// so the Metro `process.env` typings are referenced here for clean CI type checks.
declare namespace NodeJS {
  interface ProcessEnv {
    /** API base URL, inlined by Expo at build time. Validated in src/config/api.ts. */
    EXPO_PUBLIC_API_URL?: string;
  }
}
